def read(p):return json.loads(Path(p).read_text())
def href(p):return '../../'+str(p.relative_to(ROOT))
FIELDS=('frame','global_state','nmi_scene','active_controller','active_main','active_phase','calendar_and_turn_6F00_6F06','domestic_control_6F5B_6F62','cooperation_status_6F8B','all30_city_auxiliary_bytes','all30_city_owners','all30_city_gold','all30_city_reserve','all30_city_rosters','observed_officers','RAM_sha256','SRAM_sha256','RGB_sha256','PCM_sha256','whole_serialized_state_sha256')
HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>阶段十八 · 城市辅助字节与实际内政AI</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0d151b;color:#dce6e8;font:16px/1.65 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:34px 28px 90px}h1{font-size:36px;line-height:1.3;max-width:900px}h2{font-size:25px;margin-top:0}h3{font-size:18px}a{color:#9ad9c7}nav{display:flex;gap:22px;flex-wrap:wrap;margin:22px 0}section{border-top:1px solid #3b4b54;padding:28px 0;margin-top:28px}small,.note{color:#9aaeb6}label{display:inline-flex;gap:9px;align-items:center;margin:8px 18px 8px 0}select,input,button{background:#1d303a;color:#e0ebed;border:1px solid #54717b;border-radius:4px;padding:8px;font:inherit;max-width:100%}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #c4ede0;outline-offset:3px}pre{background:#101d26;max-height:460px;overflow:auto;padding:18px;font:13px/1.65 ui-monospace,monospace;white-space:pre;tab-size:4}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #374952;padding:12px;word-break:break-word}td pre{white-space:pre-wrap;max-height:220px;margin:0;padding:5px}.metrics{display:flex;gap:28px;flex-wrap:wrap;margin:20px 0}.metric strong{display:block;font-size:28px;color:#abe0cb}.screens{display:grid;grid-template-columns:1fr 1fr;gap:25px}.screens img{width:min(100%,512px);height:auto;image-rendering:pixelated;display:block;border:1px solid #334b59}.screens figure{margin:12px 0}.linkrow{display:flex;gap:18px;flex-wrap:wrap}.scroll{overflow:auto}audio{width:min(100%,600px)}.status{color:#c4e5d8}#error{color:#ffb9b0}@media(max-width:700px){main{padding:22px 16px}h1{font-size:28px}.screens{grid-template-columns:1fr}.metrics{gap:18px}th,td{padding:8px}label{display:flex}input{width:110px}}
</style><main><small>三国志2超级版 · 原ROM证据 · 阶段十八</small><h1>城市+1的实际补兵门槛<br>与尾部四字节的访问合同</h1><p>城市+1参加原内政AI读取的交叠字：<code>city[1] | city[2] &lt;&lt; 8</code>，选择门槛300。源码按原偏移保留行为。单字节正式名称及+28..31的正式名称仍缺充分证据。</p><nav><a href="#fields">逐访问合同</a><a href="#source">可读源码</a><a href="#native">原模拟器对照</a><a href="README.md">分析报告</a><a href="../phase17/index.html">阶段十七</a></nav><div class="metrics" id="metrics"></div><p class="note">原CPU施加的明确寄存器／中断输入与原Nestopia录像分别展示。775个跳转目标边界不计为源码RTS对照；未解析访问不计为已确认字段。</p><p id="error" role="alert"></p>
<section id="fields"><h2>逐个剩余访问的归类</h2><p id="access-summary"></p><label for="classification">访问归类 <select id="classification"><option value="all">全部589条旧候选</option></select></label><label for="access-search">地址或指针 <input id="access-search" placeholder="例如 A445 或 0020"></label><p id="access-count"></p><button id="access-prev">上一页</button> <button id="access-next">下一页</button><div class="scroll"><table><thead><tr><th>原bank / PC</th><th>操作／指针</th><th>新分类</th><th>合同与边界</th></tr></thead><tbody id="access-rows"></tbody></table></div><p class="linkrow"><a href="fields-static/access-contracts.json">完整访问合同JSON</a><a href="fields-static/call-effect-summaries.json">may-write摘要</a><a href="control/control-contracts.json">102个跳转表与原字节</a><a href="control/verification.json">775个原CPU跳转边界</a></p></section>
<section id="source"><h2>完整可读源码</h2><p>新增独立服务与整合入口，复用冻结的主循环、内政和远端服务。此页只查看源码和证据。</p><label for="source-select">源码文件 <select id="source-select"></select></label><button id="source-open">加载完整源码</button><p id="source-meta" class="note"></p><pre id="source-code">选择文件并加载</pre><p class="linkrow" id="source-links"></p><h3>验证范围</h3><pre id="source-receipt"></pre></section>
<section id="native"><h2>原Nestopia：同一自然母档的对照</h2><label for="case">实际流程 <select id="case"></select></label><p id="case-scope"></p><details><summary>初始母档、数值准备与完整输入计划</summary><pre id="case-provenance"></pre></details><div class="screens"><figure><label for="point-a">原帧截图A <select id="point-a"></select></label><img id="image-a" alt="原模拟器截图A"><figcaption id="caption-a"></figcaption></figure><figure><label for="point-b">原帧截图B <select id="point-b"></select></label><img id="image-b" alt="原模拟器截图B"><figcaption id="caption-b"></figcaption></figure></div><details><summary>对应截图的完整原字段</summary><pre id="point-raw"></pre></details><h3>任意两个实际帧的字段对照</h3><label for="frame-a">帧A <input id="frame-a" type="number" min="1"></label><label for="frame-b">帧B <input id="frame-b" type="number" min="1"></label><button id="frame-compare">对照实际帧</button><p class="note">任意帧字段来自逐帧原内存。上方截图始终对应选中的实际checkpoint。</p><div class="scroll"><table><thead><tr><th>原字段</th><th>帧A</th><th>帧B</th></tr></thead><tbody id="frame-rows"></tbody></table></div><h3>完整原PCM音频</h3><audio id="audio" controls preload="metadata"></audio><p id="audio-meta" class="note"></p><p class="linkrow" id="case-links"></p><h3>跨组实际结果</h3><pre id="cohort-result"></pre></section><p class="note">保留旧ROM、旧阶段源码与回放。字段正式名称未证实的部分继续使用raw／opaque名；局部菜单无差异不构成unused或padding证明。</p></main><script id="evidence" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.querySelector('#evidence').textContent),$=s=>document.querySelector(s),fmt=x=>JSON.stringify(x,null,2),hex=x=>x.toString(16).toUpperCase().padStart(4,'0');let current,points,accessPage=0;
function cell(v){let t=document.createElement('td'),p=document.createElement('pre');p.textContent=typeof v==='string'?v:fmt(v);t.append(p);return t}function row(values){let tr=document.createElement('tr');values.forEach(v=>tr.append(cell(v)));return tr}
function access(reset=false){if(reset)accessPage=0;let kind=$('#classification').value,q=$('#access-search').value.trim().toUpperCase();let all=D.accesses.filter(r=>(kind==='all'||r.classification===kind)&&(!q||`${r.physical_bank}:${hex(r.cpu)} ${r.pointer_zero_page} ${hex(r.pointer_zero_page||0)} ${r.classification}`.toUpperCase().includes(q)));accessPage=Math.max(0,Math.min(accessPage,Math.max(0,Math.ceil(all.length/25)-1)));$('#access-count').textContent=`${all.length}条匹配；第${accessPage+1}页，每页25条；完整合同保留所有候选及其边界`;$('#access-prev').disabled=accessPage===0;$('#access-next').disabled=(accessPage+1)*25>=all.length;$('#access-rows').replaceChildren(...all.slice(accessPage*25,(accessPage+1)*25).map(r=>row([`${r.physical_bank}:${hex(r.cpu)}`,`${r.op} (${hex(r.pointer_zero_page||0)}),Y`,r.classification,{pointer_kind:r.pointer_kind,Y_values:r.Y_values,proof:r.address_contract||r.exact_address_proof||r.address_proof||r.proof,limits:r.limits||r.unresolved_reason||r.reason||r.contract||r.boundary}])))}
async function source(){let s=D.sources[$('#source-select').value];try{let response=await fetch(s.href);if(!response.ok)throw new Error(`HTTP${response.status}`);let t=await response.text();let b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));let actual=[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');if(actual!==s.sha256)throw new Error('源码与冻结SHA不同');$('#source-code').textContent=t;$('#source-meta').textContent=`完整UTF8源码 · ${t.length}字符 · SHA256 ${actual}`;$('#source-links').innerHTML=`<a href="${s.href}" download>下载完整源码</a>`;$('#source-receipt').textContent=fmt(D.source_receipts)}catch(e){$('#error').textContent='源码加载失败：'+e.message}}
function point(){let a=current.checkpoints[+$('#point-a').value],b=current.checkpoints[+$('#point-b').value];for(let [side,p]of[['a',a],['b',b]]){$('#image-'+side).src=p.image_href;$('#caption-'+side).textContent=`实际frame${p.frame} · ${p.label} · 原256×240`};$('#point-raw').textContent=fmt({A:a.fields,B:b.fields})}
function compare(){let a=Number($('#frame-a').value),b=Number($('#frame-b').value);if(!Number.isInteger(a)||!Number.isInteger(b)){$('#error').textContent='帧号须为整数；现有对照保持原样。';return}a=Math.max(1,Math.min(current.frames.length,a));b=Math.max(1,Math.min(current.frames.length,b));$('#frame-a').value=a;$('#frame-b').value=b;let left=current.frames[a-1],right=current.frames[b-1];$('#frame-rows').replaceChildren(...D.frame_fields.map(k=>row([k,left[k],right[k]])));if($('#error').textContent.startsWith('帧号须为整数'))$('#error').textContent=''}
function choose(){current=D.native[$('#case').value];$('#case-scope').textContent=`${current.case} · ${current.frames.length}实际帧 · 一次公开自然母档导入 · ${current.preparation.length}个实际字节准备 · 未注入request／ready／result／pointer`;$('#case-provenance').textContent=fmt({mother:current.mother,mother_sha256:current.mother_sha256,preparation:current.preparation,preparation_groups:current.preparation_groups,input_plan:current.plan,limits:current.limits});for(let side of['a','b']){$('#point-'+side).innerHTML=current.checkpoints.map((p,i)=>`<option value="${i}">${p.frame} · ${p.label}</option>`).join('')};$('#point-b').value=current.checkpoints.length-1;point();$('#frame-a').max=$('#frame-b').max=current.frames.length;$('#frame-a').value=1;$('#frame-b').value=current.frames.length;compare();$('#audio').src=current.audio.href;$('#audio-meta').textContent=`原48000Hz／双声道16bit · ${current.audio.sample_frames}样本对 · SHA256 ${current.audio.sha256}`;$('#case-links').innerHTML=current.links.map(p=>`<a href="${p.href}">${p.label}</a>`).join('')}
$('#metrics').innerHTML=D.metrics.map(([label,count])=>`<div class="metric"><small>${label}</small><strong>${count}</strong></div>`).join('');$('#access-summary').textContent=fmt(D.static_summary);for(let name of Object.keys(D.classifications)){let o=document.createElement('option');o.value=name;o.textContent=`${name} (${D.classifications[name]})`;$('#classification').append(o)}$('#classification').onchange=()=>access(true);$('#access-search').oninput=()=>access(true);$('#access-prev').onclick=()=>{accessPage--;access()};$('#access-next').onclick=()=>{accessPage++;access()};access();$('#source-select').innerHTML=D.sources.map((s,i)=>`<option value="${i}">${s.label}</option>`).join('');$('#source-open').onclick=source;$('#case').innerHTML=D.native.map((g,i)=>`<option value="${i}">${g.case}</option>`).join('');$('#case').onchange=choose;$('#point-a').onchange=$('#point-b').onchange=point;$('#frame-compare').onclick=compare;$('#cohort-result').textContent=fmt(D.cohort_comparison);choose();source();
</script></html>'''
def main():
 static=read(OUT/'fields-static/analysis-summary.json');accesses=read(OUT/'fields-static/access-contracts.json');control=read(OUT/'control/verification.json')
 sources=[dict(label=n,href=href(ROOT/'source/recovered'/n)+'?sha='+sha(ROOT/'source/recovered'/n),sha256=sha(ROOT/'source/recovered'/n))for n in('city_auxiliary_services.py','city_auxiliary_integration.py')]
 native=[]
 for folder in sorted(RUN.iterdir()):
  if not folder.is_dir()or not(folder/'validation.json').is_file():continue
  r=read(folder/'validation.json');assert r['status']=='passed';frames=read(folder/'frame-services.json');points=read(folder/'checkpoints.json');wav=folder/'full-audio.wav'
  assert len(frames)==r['frames']and len(points)==r['checkpoint_count']and all(set(FIELDS)<=row.keys()for row in frames)
  with wave.open(str(wav),'rb')as w:sample_frames=w.getnframes();assert(w.getnchannels(),w.getsampwidth(),w.getframerate())==(2,2,48000)
  for p in points:p['image_href']=href(folder/p['image'])+'?sha='+sha(folder/p['image'])
  native.append(dict(case=folder.name,frames=[{k:row[k]for k in FIELDS}for row in frames],checkpoints=points,
    mother=r.get('mother',r.get('mother_state')),mother_sha256=r.get('mother_sha256'),preparation=r['preparation'],preparation_groups=r['preparation_groups'],plan=read(folder/'input-plan.json'),limits=r.get('limits',r.get('scope')),
    audio=dict(href=href(wav)+'?sha='+sha(wav),sha256=sha(wav),sample_frames=sample_frames),
    links=[dict(href=href(folder/name),label=name)for name in('validation.json','repeat-validation.json','frame-services.json','input-plan.json','preparation.json')]))
 assert len(native)==5
 source_receipts={name:read(OUT/name)for name in('source-integration.json','services/validation.json')}
 for receipt in source_receipts.values():
  assert receipt['status']=='passed'and not receipt.get('quick',False)
  for path,digest in receipt['source_sha256'].items():assert sha(ROOT/path)==digest,path
 source_receipts={name:{k:v for k,v in receipt.items()if k in('status','rom_cpu_case_count','complete_return_count','strict_prefix_count','rom_cpu_sequence_count','actual_caller_RTS_count','source_guard_case_count','scope','comparison','limits','limitations')}for name,receipt in source_receipts.items()}
 data=dict(static_summary={k:static[k]for k in('instruction_count','baseline_candidate_count','classification_counts')},classifications=accesses['classification_counts'],accesses=accesses['accesses'],sources=sources,native=native,frame_fields=FIELDS,
   metrics=[('原指令位置',control['raw_instruction_positions_verified']),('旧候选访问',589),('原CPU跳转边界',775),('原模拟器组数',len(native))],
   source_receipts=source_receipts,cohort_comparison=read(RUN/'cohort-comparison.json'))
 html=HTML.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'));(OUT/'index.html').write_text(html)
 links=re.findall(r'href="([^"#]+)"',html);pins={}
 for folder in('control','fields-static','services','runtime'):
  for p in(OUT/folder).rglob('*'):
   if p.is_file()and '__pycache__'not in p.parts:pins[str(p.relative_to(ROOT))]=sha(p)
 for s in sources:
  p=ROOT/'source/recovered'/s['label'];pins[str(p.relative_to(ROOT))]=sha(p)
 pins['analysis/phase18/source-integration.json']=sha(OUT/'source-integration.json')
 result=dict(status='passed',schema='phase18-evidence-browser-static-v1',HTML_sha256=sha(OUT/'index.html'),builder_sha256=sha(Path(__file__)),dependency_pins=pins,native_case_count=5,source_file_count=2,frame_field_count=len(FIELDS),DOM_ID_count=len(re.findall(r'id="([^"]+)"',html)),source_pipeline_executed=False)
 (OUT/'browser-static-check.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:result[k]for k in('status','HTML_sha256','native_case_count','source_file_count')}))
if __name__=='__main__':main()
